// clearance ring: grow a measured outline by the fit clearance
linear_extrude(6) difference() { offset(delta=4) neck(); offset(delta=0.15) neck(); }
module neck() circle(d=43, $fn=128);

function tooth(i, n, r) = [r*cos(i*360/n), r*sin(i*360/n)];
poly = [for (i=[0:11]) tooth(i, 12, 10)];
linear_extrude(3) polygon(poly);

wall = 1.6;
ring_od = neck_d + clearance + 2*wall;
neck_d = 43; clearance = 0.25;  // order does not matter
